package main

import (
	"fmt"
	"math"
)
func main() {
    var cchico, ccebolinha, quant int
    fmt.Scan(&cchico, &ccebolinha, &quant)
    animais := make([]string, quant)
    for i := 0 ; i < quant ; i++ {
        fmt.Scan(&animais[i])
    }
    patas := 0

    for _, valor := range animais {
        if valor == "c" {
            patas+= 4
        } else if valor == "g" {
            patas+= 2 
        } else if valor == "v" {
            patas+= 4
        }
    }

    fmt.Println(patas)
    dif1 := math.Abs(float64(cchico) - float64(patas))
    dif2 := math.Abs(float64(ccebolinha) - float64(patas))
    if dif1 < dif2 {
        fmt.Println("Chico Bento")
    } else if dif2 < dif1 {
        fmt.Println("Cebolinha")
    } else if dif1 == dif2{
        fmt.Println("empate")
    }


}
